sp_widget.client_script:
api.controller=function() {
  /* widget controller */
  var c = this;
};

sp_widget.css:
.policy-wrapper {
  display: flex;
  gap: 40px;
  background-color: #f6e7db;
  padding: 30px;
  font-family: 'Poppins', sans-serif;
}

.policy-sidebar {
  max-width: 250px;
}

.policy-sidebar h2 {
  font-size: 22px;
  font-weight: bold;
  margin-bottom: 20px;
}

.policy-list {
  list-style: none;
  padding: 0;
  margin: 0;
}

.policy-list li {
  margin: 12px 0;
}

.policy-list a {
  text-decoration: none;
  color: #333;
  font-size: 16px;
  transition: color 0.3s ease;
}

.policy-list a:hover {
  color: #007bff;
}

.policy-content {
  flex: 1;
  background: #fff;
  padding: 20px;
  border-radius: 10px;
  min-height: 300px;
  color: #333;
}
